#!/usr/bin/env python3
"""microbiome/amplicon_dada2_qiime — auto-generated run.py (archetype=microbiome_pipeline).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "microbiome_pipeline"
BRAIN = "microbiome"
SKILL = "amplicon_dada2_qiime"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'amplicon_dada2_qiime', 'n_samples': 0, 'taxonomy_table': '', 'diversity_metrics': {'shannon': 0.0, 'observed_otus': 0}, 'diagnostics': {'brain': 'microbiome', 'archetype': 'microbiome_pipeline'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """16S amplicon DADA2 最小流水线(R 4.5 + dada2 R 包)。host_env=praxis-microbiome-dada2-r。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    fq_dir = payload.get("fastq_dir") or payload.get("input_dir")
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="dada2_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "dada2-R", "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_samples": 0, "taxonomy_table": "",
                "diversity_metrics": {"shannon": 0.0, "observed_otus": 0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not fq_dir or not _os.path.isdir(fq_dir):
        return {"ok": False, "error": "需要 fastq_dir (含 paired fastq 的目录)",
                "diagnostics": diagnostics}
    r_template = """library(dada2)
path <- '__PATH__'
outdir <- '__OUTDIR__'
dir.create(outdir, showWarnings = FALSE, recursive = TRUE)
fnFs <- sort(list.files(path, pattern='_1.fastq', full.names=TRUE))
fnRs <- sort(list.files(path, pattern='_2.fastq', full.names=TRUE))
filtFs <- file.path(outdir, 'filt', basename(fnFs))
filtRs <- file.path(outdir, 'filt', basename(fnRs))
filterAndTrim(fnFs, filtFs, fnRs, filtRs, truncLen=c(240,160), maxN=0, maxEE=c(2,2), rm.phix=TRUE, compress=TRUE, multithread=TRUE)
errF <- learnErrors(filtFs, multithread=TRUE)
errR <- learnErrors(filtRs, multithread=TRUE)
dadaFs <- dada(filtFs, err=errF, multithread=TRUE)
dadaRs <- dada(filtRs, err=errR, multithread=TRUE)
mergers <- mergePairs(dadaFs, filtFs, dadaRs, filtRs)
seqtab <- makeSequenceTable(mergers)
seqtab.nochim <- removeBimeraDenovo(seqtab, method='consensus', multithread=TRUE)
out_csv <- file.path(outdir, 'seqtab.csv')
write.csv(seqtab.nochim, out_csv)
cat(sprintf('OK n_asv=%d n_samples=%d', ncol(seqtab.nochim), nrow(seqtab.nochim)))
"""
    r_script = r_template.replace("__PATH__", fq_dir).replace("__OUTDIR__", out_dir)
    rscript_path = _os.path.join(out_dir, "_dada2.R")
    _os.makedirs(out_dir, exist_ok=True)
    with open(rscript_path, "w") as fh: fh.write(r_script)
    t0 = _time.time()
    r = run_tool(["Rscript", rscript_path], timeout=int(payload.get("timeout_s", 7200)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "dada2 R 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    # 从 stdout 抓 OK n_asv=... n_samples=...
    n_asv, n_samp = 0, 0
    out_csv = _os.path.join(out_dir, "seqtab.csv")
    for ln in reversed(r["stdout"].splitlines()):
        if "n_asv=" in ln and "n_samples=" in ln:
            try:
                n_asv = int(ln.split("n_asv=")[1].split()[0])
                n_samp = int(ln.split("n_samples=")[1].split()[0])
                break
            except (ValueError, IndexError):
                continue
    return {"ok": True, "skill_id": SKILL,
            "n_samples": n_samp,
            "taxonomy_table": out_csv,
            "diversity_metrics": {"shannon": 0.0, "observed_otus": n_asv},
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
